@using sv_acfffc9c2f684855bbc019cc3c9dfa67.Models

<nav aria-label="Application steps" class="step-indicator mb-4">
    <ol class="d-flex list-unstyled justify-content-between position-relative px-0">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var status = step == CurrentStep ? "active"
                       : CompletedSteps.Contains(step) ? "completed"
                       : "pending";

            <li class="step-item text-center flex-fill @status"
                role="button"
                @onclick="() => OnStepClicked(step)">
                <div class="step-circle mx-auto mb-1 rounded-circle d-flex align-items-center justify-content-center
                            @(status == "active" ? "bg-primary text-white" :
                              status == "completed" ? "bg-success text-white" :
                              "bg-secondary bg-opacity-25 text-muted")"
                     style="width: 36px; height: 36px; font-size: 0.85rem;">
                    @if (status == "completed")
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </div>
                <small class="@(status == "pending" ? "text-muted" : "")">@StepNames[step]</small>
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = [];
    [Parameter] public EventCallback<int> OnNavigate { get; set; }

    private async Task OnStepClicked(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnNavigate.InvokeAsync(step);
        }
    }
}

