@page "/apply"
@using sv_acfffc9c2f684855bbc019cc3c9dfa67.Models
@using sv_acfffc9c2f684855bbc019cc3c9dfa67.Services
@using sv_acfffc9c2f684855bbc019cc3c9dfa67.Components.Pages.Apply

@rendermode InteractiveServer

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4 text-center">Job Application</h2>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   OnNavigate="NavigateToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="formModel.Personal"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="() => CompleteAndAdvance(0)" />
            break;

        case 1:
            <WorkHistoryStep Entries="formModel.WorkEntries"
                             OnNext="() => CompleteAndAdvance(1)"
                             OnBack="() => GoBack()" />
            break;

        case 2:
            <ReferencesStep Entries="formModel.References"
                            OnNext="() => CompleteAndAdvance(2)"
                            OnBack="() => GoBack()" />
            break;

        case 3:
            <CoverLetterStep @bind-CoverLetter="formModel.CoverLetter"
                             OnNext="() => CompleteAndAdvance(3)"
                             OnBack="() => GoBack()" />
            break;

        case 4:
            <ReviewStep Model="formModel"
                        OnEditStep="NavigateToStep"
                        OnBack="() => GoBack()"
                        SubmitApplication="SubmitAsync" />
            break;
    }
</div>

@code {
    private ApplicationFormModel formModel = new();
    private int currentStep;
    private HashSet<int> completedSteps = [];

    private void CompleteAndAdvance(int step)
    {
        completedSteps.Add(step);
        currentStep = step + 1;
    }

    private void GoBack()
    {
        if (currentStep > 0) currentStep--;
    }

    private void NavigateToStep(int step)
    {
        if (completedSteps.Contains(step))
        {
            currentStep = step;
        }
    }

    private async Task<int> SubmitAsync()
    {
        return await ApplicationService.SubmitApplicationAsync(formModel.ToRecord());
    }
}

